<script setup>
const props=defineProps({rows:{type:Array,required:true},batches:{type:Array,required:true},fallback:{type:Object,required:true}}),emit=defineEmits(['update']);
function add(){const b=props.batches[0],stock=b?.layout.stock;emit('update',[...props.rows,{material:b?.material??'oak',thicknessMm:b?Math.round(b.thickness*1000000)/1000:18,stockLengthMm:stock?.stockLengthMm??2440,stockWidthMm:stock?.stockWidthMm??1220,price:props.fallback[b?.material??'oak']}]);}
function set(index,key,value){emit('update',props.rows.map((row,i)=>i===index?{...row,[key]:value}:row));}
</script>
<template><section aria-label="Stock sheet price overrides"><h4>Stock sheet price overrides</h4><button :disabled="rows.length>=128" @click="add">Add stock price override</button><fieldset v-for="(row,i) in rows" :key="i"><legend>Stock price {{ i+1 }}</legend><label>Material<select :value="row.material" :aria-label="'Stock price '+(i+1)+' material'" @change="set(i,'material',$event.target.value)"><option>oak</option><option>birch</option><option>white</option></select></label><label v-for="field in ['thicknessMm','stockLengthMm','stockWidthMm']" :key="field">{{ field }}<input :value="row[field]" type="number" step="0.001" :aria-label="'Stock price '+(i+1)+' '+field" @input="set(i,field,$event.target.value===''?NaN:Number($event.target.value))"></label><label>Sheet price<input :value="row.price" inputmode="decimal" :aria-label="'Stock price '+(i+1)+' amount'" @input="set(i,'price',$event.target.value)"></label><button @click="emit('update',rows.filter((_,n)=>n!==i))">Remove stock price {{ i+1 }}</button></fieldset><p class="hint">Exact matches use dimensions to 0.001 mm. Length/width order matters; rotation is not inferred. Unmatched stock uses the material fallback. Duplicate matches are rejected; zero is an explicit price. Changes affect draft rates only.</p></section></template>
